import React, { Component } from "react";
import { Pagination } from "react-bootstrap";

import ReactPageScroller, { SectionContainer, setDisableScroll} from "react-page-scroller";

import "./pages/index.css";
import LHeader from "./components/LHeader";
import About from "./components/About";
import Skills from "./components/Skills";
import Projects from "./components/Projects";
import Thesis from "./components/Thesis";
import Publications from "./components/Publications";
import Experience from "./components/Experience";
import Footer from "./components/Footer";
import $ from "jquery";


export default class FullPage extends Component {
  constructor(props) {
    super(props);
    this.state = { 
      sharedData: {},
      resumeData: {},
      currentPage: null, 
    };
  }


  applyPickedLanguage(pickedLanguage, oppositeLangIconId) {
    document.documentElement.lang = pickedLanguage;
    var resumePath =
      document.documentElement.lang === window.$primaryLanguage
        ? `res_primaryLanguage.json`
        : `res_secondaryLanguage.json`;
    this.loadResumeFromPath(resumePath);
  }

  loadResumeFromPath(path) {
    $.ajax({
      url: path,
      dataType: "json",
      cache: false,
      success: function (data) {
        this.setState({ resumeData: data });
      }.bind(this),
      error: function (xhr, status, err) {
        alert(err);
      },
    });
  }


  componentDidMount() {
    this.loadSharedData();
    this.applyPickedLanguage(
      window.$primaryLanguage,
      window.$secondaryLanguageIconId
    );

  }

  loadSharedData() {
    $.ajax({
      url: `portfolio_shared_data.json`,
      dataType: "json",
      cache: false,
      success: function (data) {
        this.setState({ sharedData: data });
        document.title = `${this.state.sharedData.basic_info.name}`;
      }.bind(this),
      error: function (xhr, status, err) {
        alert(err);
      },
    });
  }

  handlePageChange = number => {
    this.setState({ currentPage: number });
  };

  handleBeforePageChange = number => {
    const currentPage = this.state.currentPage;
    const nextPage = number;
    if (currentPage !== 3) {
      const p = document.querySelector('.project-container2')
      p.scrollTo(0, 0);
    } else if (currentPage !== 5) {
      const p = document.querySelector('.project-container')
      p.scrollTo(0, 0);
    }

    if (this.state.currentPage === 5) {
      const p = document.querySelector('.project-container')
      if (p) {
        const scrollTop = p.scrollTop;
        const isAtTop = scrollTop === 0;
        const scrollHeight = p.scrollHeight;
        const clientHeight = p.clientHeight; 
        const isAtBottom = scrollTop + clientHeight >= scrollHeight;
        console.log(currentPage, nextPage, isAtTop, isAtBottom, scrollTop, clientHeight, scrollHeight);
        if ((currentPage > nextPage && !isAtTop) || (currentPage < nextPage && !isAtBottom)) {
          return false;
        }
      }
    } else if (this.state.currentPage === 3) {
      const p = document.querySelector('.project-container2')
      if (p) {
        const scrollTop = p.scrollTop;
        const isAtTop = scrollTop === 0;
        const scrollHeight = p.scrollHeight;
        const clientHeight = p.clientHeight; 
        const isAtBottom = scrollTop + clientHeight + 2 >= scrollHeight;
        console.log(currentPage, nextPage, isAtTop, isAtBottom, scrollTop, clientHeight, scrollHeight);
        if ((currentPage > nextPage && !isAtTop) || (currentPage < nextPage && !isAtBottom)) {
          return false;
        }
      }
    }
    return true;
  };

  getPagesNumbers = () => {
    const pageNumbers = [];
    let page_list = {
      0 : "Main",
      1 : "About me",
      2 : "Skills",
      3 : "Experience",
      4 : "Publications",
      5 : "Projects",
    }
    for (let i = 0; i <= 5; i++) {
      pageNumbers.push(
        <Pagination.Item key={i} active={this.state.currentPage === i} onClick={() => this.handlePageChange(i)}>
          {page_list[i]}
        </Pagination.Item>,
      );
    }
    return [...pageNumbers];
  };

  render() {
    const pagesNumbers = this.getPagesNumbers();

    return (
      <React.Fragment>
        <ReactPageScroller
          pageOnChange={this.handlePageChange}
          onBeforePageScroll={this.handleBeforePageChange}
          customPageNumber={this.state.currentPage}
          renderAllPagesOnFirstRender="true"
        >
          <LHeader sharedData={this.state.sharedData.basic_info} />
          <SectionContainer height={65}>
            <About
              resumeBasicInfo={this.state.resumeData.basic_info}
              sharedBasicInfo={this.state.sharedData.basic_info}
            />
          </SectionContainer>
          <SectionContainer height={40}>
            <Skills
              sharedSkills={this.state.sharedData.skills}
              resumeBasicInfo={this.state.resumeData.basic_info}
            />
          </SectionContainer>
          <SectionContainer height={100}>
            <div
              className="scrollable-section"
              style={{
                height: '100vh',
                width: '110vw',
                overflowY: 'auto',
                overflowX: 'hidden',
                boxSizing: 'border-box',
                scrollbarGutter: 'stable',
                paddingRight: '1rem', // optional, scroll바 안 가리게
              }}
            >
              <div className="project-container2">
                <Experience
                  resumeExperience={this.state.resumeData.experience}
                  resumeBasicInfo={this.state.resumeData.basic_info}
                />
              </div>
            </div>
          </SectionContainer>
          <SectionContainer height={70}>
            <Publications
              publications={this.state.sharedData.publications}
              resumeBasicInfo={this.state.resumeData.basic_info}
            />
          </SectionContainer>
          <SectionContainer height={100}>
            <div className="project-container">
              <Projects
                resumeProjects={this.state.resumeData.projects}
                resumeBasicInfo={this.state.resumeData.basic_info}
              />
            </div>
          </SectionContainer>
        </ReactPageScroller>
        <Pagination className="pagination-additional-class" size="lg">
          {pagesNumbers}
        </Pagination>
      </React.Fragment>
    );
  }
}
