import React, { Component } from "react";

class Publications extends Component {

  render() {
    if (this.props.publications && this.props.resumeBasicInfo) {
      var sectionName = this.props.resumeBasicInfo.section_name.publications;
      var posters = this.props.publications.posters.map(function (poster, i) {
        return( 
            <li>
              <div className="title">{poster.name}</div>
              <div className="author">
                {poster.authors.map((author, index) => (
                      <span key={index}>
                        {index > 0 && ", "}
                        {author === "Jinwon Lee" ? <strong>{author}</strong> : author}
                      </span>
                ))}
              </div>
              <div className="place">{poster.place} <a href={poster.url}>Poster</a></div>
            </li>
            );
      });
      var thesis = this.props.publications.thesis.map(function (thesis, i) {
        return( 
            <li>
              <div className="title">{thesis.name}</div>
              <div className="place">{thesis.degree} <a href={thesis.url}>Thesis</a></div>
            </li>
            );
      });
      var preprints = this.props.publications.preprints.map(function (preprint, i) {
        return( 
            <li>
              <div className="title">{preprint.name}</div>
              <div className="author">
                {preprint.authors.map((author, index) => (
                      <span key={index}>
                        {index > 0 && ", "}
                        {author === "Jinwon Lee" ? <strong>{author}</strong> : author}
                      </span>
                ))}
              </div>
              <div className="place">{preprint.place} <a href={preprint.url}>Paper</a></div>
            </li>
            );
      });
    }

    return (
      <section id="publications">
        <div className="col-md-12">
          <div className="col-md-12">
            <h1 className="section-title">
              <span className="text-white">{sectionName}</span>
            </h1>
          </div>
          <div>
            <span className="poster-title">Posters</span>
            <ul className="publication-list">
            {posters}
            </ul>
          </div>
          <br />
          <br />
          <div>
            <span className="poster-title">Preprints</span>
            <ul className="publication-list">
            {preprints}
            </ul>
          </div>
          <br />
          <br />
          <div>
            <span className="poster-title">Thesis</span>
            <ul className="publication-list">
            {thesis}
            </ul>
          </div>

        </div>
      </section>
    );
  }
}

export default Publications;
